begin;
create table if not exists public.ai_workforce_conversations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),employee_code text not null check(employee_code in('sales-ai','crm-ai','marketing-ai','whatsapp-ai','voice-ai','operations-ai','finance-ai','executive-ai')),title text not null check(char_length(title)between 1 and 120),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists public.ai_workforce_messages(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),conversation_id uuid not null references public.ai_workforce_conversations(id)on delete cascade,role text not null check(role in('user','assistant')),content text not null check(char_length(content)between 1 and 100000),model text,input_tokens integer not null default 0 check(input_tokens>=0),output_tokens integer not null default 0 check(output_tokens>=0),cost_estimate numeric(18,8)not null default 0 check(cost_estimate>=0),recommendation_only boolean not null default true check(recommendation_only),created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create index if not exists ai_workforce_conversation_search_idx on public.ai_workforce_conversations(organization_id,workspace_id,employee_code,updated_at desc)where deleted_at is null;
create index if not exists ai_workforce_message_history_idx on public.ai_workforce_messages(organization_id,workspace_id,conversation_id,created_at);
alter table public.ai_workforce_conversations enable row level security;alter table public.ai_workforce_messages enable row level security;
create policy "ai_workforce_conversation_read" on public.ai_workforce_conversations for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);
create policy "ai_workforce_conversation_insert" on public.ai_workforce_conversations for insert to authenticated with check(created_by=auth.uid()and public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);
create policy "ai_workforce_conversation_update" on public.ai_workforce_conversations for update to authenticated using(created_by=auth.uid()and public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null)with check(created_by=auth.uid());
create policy "ai_workforce_message_read" on public.ai_workforce_messages for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);
create policy "ai_workforce_message_insert" on public.ai_workforce_messages for insert to authenticated with check(created_by=auth.uid()and recommendation_only and public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null and exists(select 1 from public.ai_workforce_conversations c where c.id=conversation_id and c.organization_id=organization_id and c.workspace_id=workspace_id and c.deleted_at is null));
commit;
